static inline void sm_stage2_insect_frog_predict(const float* f, uint8_t* label, uint8_t* conf)
{
    sm_predict(&sm_stage2_insect_frog, f, label, conf);
}

/* stage-2 model for a group id, or NULL if that group has none */
static inline const sm_model_t* sm_stage2_for_group(uint8_t group)
{
    switch (group)
    {
    case SC_BIRD:
        return &sm_stage2_bird;
    case SC_MAMMAL:
        return &sm_stage2_mammal;
    case SC_INSECT_FROG:
        return &sm_stage2_insect_frog;
    default:
        return 0;
    }
}

